from math import gcd
class Solution:
    def goodSubsequenceQueries(self, nums, p, queries):
        n = len(nums); ans = 0
        for i, v in queries:
            nums[i] = v
            b = [x // p if x % p == 0 else 0 for x in nums]
            g = 0
            for x in b:
                g = gcd(g, x)
            if g != 1:
                continue
            c = sum(1 for x in b if x)
            if c < n:
                ans += 1
                continue
            pre = [0] * (n + 1)
            suf = [0] * (n + 1)
            for j, x in enumerate(b):
                pre[j+1] = gcd(pre[j], x)
            for j in range(n - 1, -1, -1):
                suf[j] = gcd(suf[j+1], b[j])
            if any(gcd(pre[j], suf[j+1]) == 1 for j in range(n)):
                ans += 1
        return ans

