    public int goodSubsequenceQueries(int[] nums, int p, int[][] queries) {
        int n = nums.length, ans = 0;
        for (int[] q : queries) {
            nums[q[0]] = q[1];
            int[] b = new int[n];
            int g = 0, c = 0;
            for (int i = 0; i < n; i++) {
                b[i] = nums[i] % p == 0 ? nums[i] / p : 0;
                g = gd(g, b[i]);
                if (b[i] != 0) c++;
            }
            if (g != 1) continue;
            if (c < n) { ans++; continue; }
            int[] pre = new int[n + 1], suf = new int[n + 1];
            for (int i = 0; i < n; i++) pre[i+1] = gd(pre[i], b[i]);
            for (int i = n - 1; i >= 0; i--) suf[i] = gd(suf[i+1], b[i]);
