from math import gcd
class Solution:
    def goodSubsequenceQueries(self, nums, p, queries):
        n = len(nums)
        size = 1
        while size < n:
            size *= 2
        t = [0] * (2 * size)
        for i, v in enumerate(nums):
            t[size + i] = v // p if v % p == 0 else 0
        for i in range(size - 1, 0, -1):
            t[i] = gcd(t[2*i], t[2*i+1])
        cnt = sum(1 for v in nums if v % p == 0)
        def upd(i, v):
            i += size
            t[i] = v
            i //= 2
            while i:
                t[i] = gcd(t[2*i], t[2*i+1])
                i //= 2
        def qry(l, r):
            res = 0
            l += size; r += size
            while l < r:
                if l & 1:
                    res = gcd(res, t[l]); l += 1
                if r & 1:
                    r -= 1; res = gcd(res, t[r])
                l //= 2; r //= 2
            return res
        ans = 0
        for i, v in queries:
            if nums[i] % p == 0:
                cnt -= 1
            nums[i] = v
            if v % p == 0:
                cnt += 1
            upd(i, v // p if v % p == 0 else 0)
            if qry(0, n) == 1 and (cnt < n or n >= 17 or
                    any(gcd(qry(0, j), qry(j+1, n)) == 1 for j in range(n))):
                ans += 1
        return ans

